import { describe, it, expect } from 'vitest';
import * as cheerio from 'cheerio';
import { formatInternalLink } from '@utils/url';

// Why: The contract test reflects the HTML structure generated by
// CardsFilterableBlock, sekcja "Obszary wsparcia":
// category filters + grid/list view switcher + lazy load) to detect
// regressions in rendering without running the full build. The test does NOT check
// JavaScript (filters/observers run in the browser), static HTML only.
// Wzorzec: about-law-contract.test.ts.

interface Category {
  id: string;
  label: string;
}

interface FilterableItem {
  title: string;
  subtitle?: string;
  image?: string;
  initials?: string;
  badge?: string;
  bonus?: string;
  rate?: string;
  features?: string[];
  description?: string;
  cta?: { label: string; href: string };
  category?: string;
}

interface FilterableData {
  id?: string;
  locale?: 'pl' | 'en';
  heading: string;
  description: string;
  categories: Category[];
  items: FilterableItem[];
}

